 function open(push=true){if(active)return;if(!routeValid())return false;if(!signed){if(typeof openLogin==='function')openLogin("Sign in to explore World.");else if(typeof show==='function')show('#login');return false}if(window.ShiyuOperations&&!window.ShiyuOperations.enterWorld())return;entryArmedAt=0;wheelSum=0;wheelHandled=false;ensure();returnFocus=document.activeElement;returnURL=location.href;active=true;document.body.classList.add('world-active');mountModeCord();mountFullscreenCord();for(const child of document.body.children)if(child!==root&&!child.matches('.mode-pull-cord,.shiyu-update-prompt,.space-home-tab,.desktop-pet')&&!['SCRIPT','STYLE','LINK','DIALOG'].includes(child.tagName)){inertBefore.set(child,child.inert);child.inert=true}root.hidden=false;if(!renderWorld())return false;root.scrollTop=0;if(push)setURL();delete document.documentElement.dataset.entryPage;root.querySelector('.world-content').focus({preventScroll:true});if(push&&!reduced())root.animate([{transform:'translateY(-8vh)',opacity:.3},{transform:'translateY(0)',opacity:1}],{duration:420,easing:'cubic-bezier(.2,.7,.2,1)'})}
